solution.solution.cpp:
#include <vector>

int secondLargest(const std::vector<int>& values)
{
    int largest{ values[0] };
    bool hasSecond{ false };
    int second{ values[0] };
    for (int value : values)
    {
        if (value > largest)
        {
            second = largest;
            hasSecond = true;
            largest = value;
        }
        else if (value < largest && (!hasSecond || value > second))
        {
            second = value;
            hasSecond = true;
        }
    }
    return hasSecond ? second : largest;
}

unitTests:
TEST("ordinary list") { CHECK_EQ(secondLargest({ 4, 9, 7, 2 }), 7); }
TEST("the maximum appears twice") { CHECK_EQ(secondLargest({ 4, 9, 7, 9 }), 7); }
TEST("largest comes first") { CHECK_EQ(secondLargest({ 10, 3, 8 }), 8); }
TEST("negatives") { CHECK_EQ(secondLargest({ -5, -2, -9 }), -5); }
TEST("all the same") { CHECK_EQ(secondLargest({ 6, 6, 6 }), 6); CHECK_EQ(secondLargest({ 1 }), 1); }

